entries[22589] = { ["name"] = "Atiesh, Hohestab des Wächters", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n130 - 243 Schaden Tempo 2.90\n(64.31 Schaden pro Sekunde)\n+31 Ausdauer\n+32 Intelligenz\n+24 Willenskraft\nHaltbarkeit 145 / 145\nKlassen: Magier\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Chance mit Zaubern zu treffen um 2%.\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 150.\nAnlegen: Erhöht die Chance aller Gruppenmitglieder, die sich im Umkreis von 30 befinden, auf einen kritischen Treffer mit Zaubern um 2%.\nBenutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)" }
