entries[22630] = { ["name"] = "Atiesh, Hohestab des Wächters", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n130 - 243 Schaden Tempo 2.90\n(64.31 Schaden pro Sekunde)\n+30 Ausdauer\n+29 Intelligenz\nHaltbarkeit 145 / 145\nKlassen: Hexenmeister\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Chance, einen kritischen Treffer durch Zauber zu erzielen, um 2%.\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 150.\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung aller Gruppenmitglieder, die sich im Umkreis von 30 befinden, um bis zu 33.\nBenutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)" }
entries[22631] = { ["name"] = "Atiesh, Hohestab des Wächters", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n130 - 243 Schaden Tempo 2.90\n(64.31 Schaden pro Sekunde)\n+28 Ausdauer\n+28 Intelligenz\n+27 Willenskraft\nHaltbarkeit 145 / 145\nKlassen: Priester\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte verursachte Heilung aller Gruppenmitglieder, die sich im Umkreis von 30 befinden, um bis zu 62.\nAnlegen: Erhöht Euren Zauberschaden um bis zu 120 und Eure Heilung um bis zu 300.\nBenutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)" }
entries[22632] = { ["name"] = "Atiesh, Hohestab des Wächters", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n130 - 243 Schaden Tempo 2.90\n(64.31 Schaden pro Sekunde)\n+28 Ausdauer\n+28 Intelligenz\n+27 Willenskraft\nHaltbarkeit 145 / 145\nKlassen: Druide\nBenötigt Stufe 60\nAnlegen: Stellt alle 5 Sek. 11 Punkt(e) Mana bei allen Gruppenmitgliedern, die sich im Umkreis von 30 befinden, wieder her.\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 300.\nAnlegen: +420 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\nBenutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)" }
