entries[23794] = { ["name"] = "Zanzas ewiger Glanz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\nBenutzen: Erhöht die Chance, feindliche Zauber zu reflektieren, um 3%. Hält 2 Stunden lang an. Der erste Angriffszauber gegen den Nutzer wird automatisch reflektiert. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein.\n\"Gesegnet mit Zanzas Mojo!\"" }
